def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if len(hist) == 0:
        raise ValueError("hist must not be empty")
    if len(field_names) != hist.dim():
        raise ValueError("field_names must have the same length as hist's dim")
    if make_value is not None and not callable(make_value):
        raise TypeError("make_value must be a callable, if provided")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("invalid get_coordinate")
    if not isinstance(scale, (None.__class__, bool)):
        raise TypeError("scale must be a bool or None")
    values = [None] * len(hist)
    if make_value is not None:
        for i, bin_ in enumerate(hist):
            values[i] = make_value(bin_)
    else:
        for i, bin_ in enumerate(hist):
            values[i] = bin_.content
    coord = []
    if get_coordinate == "left":
        for i, bin_ in enumerate(hist):
            coord.append(bin_.left)
    elif get_coordinate == "right":
        for i, bin_ in enumerate(hist):
            coord.append(bin_.right)
    elif get_coordinate == "middle":
        for i, bin_ in enumerate(hist):
            coord.append(bin_.mid)
    points = [coord, values]
    graph = Graph(points)
    if scale:
        graph.scale = hist.scale
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not isinstance(hist, (list, tuple)):
        raise TypeError("hist must be a list or tuple")

    graph = []
    for bin_ in hist:
        if not isinstance(bin_, (list, tuple)):
            raise TypeError("hist bins must be lists or tuples")

        if len(bin_) != 2:
            raise ValueError("hist bins must have 2 elements")

        if make_value is None:
            value = bin_[0]
        else:
            value = make_value(bin_)

        if not isinstance(value, (int, float)):
            raise TypeError("make_value must return a scalar value")

        x_coord = bin_[0]
        y_coord = bin_[1]

        if get_coordinate == "left":
            coord = x_coord
        elif get_coordinate == "right":
            coord = x_coord + y_coord
        elif get_coordinate == "middle":
            coord = x_coord + y_coord / 2.0
        else:
            raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

        graph_point = [coord]
        for field_name in field_names:
            if field_name == "x":
                graph_point.append(x_coord)
            elif field_name == "y":
                graph_point.append(y_coord)
            elif field_name == "y_mean":
                graph_point.append(bin_[1])
            elif field_name == "y_mean_error":
                if isinstance(bin_, tuple) and len(bin_) == 3:
                    graph_point.append(bin_[2])
                else:
                    raise ValueError("bin_ must have three elements when using y_mean_error field_name")
            else:
                raise ValueError(f"unknown field_name {field_name}")

        graph.append(graph_point)

    if scale and scale != True:
        graph = [graph_point * scale for graph_point in graph]

    return graph

