def verify_relayable_signature(public_key, doc, signature):
    # Verify that the signature matches the message digest using the public key
    message_digest = xml_crypto.compute_message_digest(doc)
    xml_crypto.verify_signature(signature, message_digest, public_key)

    # Ensure that the signature is valid for the specified XML elements
    signature_elements = xml_crypto.get_signature_elements(signature)
    for element in signature_elements:
        if element not in doc.xml_elements:
            return False

    return True

